def initial_nodes():
    nodes = np.asarray(NODES, dtype=float).copy()
    # Approach the lower peg from the near side; the previous standing lead
    # crossed the new far-side left post. Reflecting this prefix preserves
    # every chord length and meets the unchanged node 28 at y=.014.
    nodes[:29, 1] = .028-nodes[:29, 1]
    return nodes


