def geometry():
    """Current probe fixture; save these dimensions in every run's config.

    The first jig's posts caught the working tail. Put the posts on the far
    side, keeping the original short pegs. The old constants above remain the
    legacy geometry for replaying recordings made before this revision.
    """
    return dict(version='far-supports-v3', peg_radius=PEG_RADIUS,
                peg_y_ends=PEG_Y_ENDS, pegs=PEGS,
                supports=[(name, (pos[0], .096, pos[2]), size)
                          for name, pos, size in SUPPORTS])
